{
  "tests": [
    {
      "id": "ca-et-factures-mois",
      "titre": "Tableau de bord : CA du mois et nombre de factures",
      "setup": "Connecté avec le compte de démo, sur le tableau de bord, sans filtre.",
      "etapes": [
        "Cliquer sur le menu « Factures »."
      ],
      "resultat_attendu": "Le CA du mois et le nombre de Factures du mois affichés correspondent respectivement au total et au nombre de factures de la liste.",
      "verifications": [
        "FAIL if le CA du mois affiché est différent du total affiché dans la liste des factures.",
        "FAIL if le nombre de Factures du mois affiché est différent du nombre de factures indiqué dans la liste."
      ],
      "releves": [
        {
          "ecran": "tableau-de-bord",
          "vue": "defaut"
        },
        {
          "ecran": "liste-des-factures",
          "vue": "defaut"
        }
      ],
      "regles_calculables": [
        {
          "type": "egalite",
          "a": {
            "ecran": "tableau-de-bord",
            "champ": "CA du mois"
          },
          "b": {
            "ecran": "liste-des-factures",
            "champ": "Total"
          }
        },
        {
          "type": "egalite",
          "a": {
            "ecran": "tableau-de-bord",
            "champ": "Factures du mois"
          },
          "b": {
            "ecran": "liste-des-factures",
            "champ": "Nombre de factures"
          }
        }
      ],
      "passages_de_la_source": [
        "Le « CA du mois » du [[tableau-de-bord]] est égal au total de la [[liste-des-factures]].",
        "Le nombre de « Factures du mois » du [[tableau-de-bord]] est égal au nombre de factures de la [[liste-des-factures]]."
      ],
      "questions": []
    },
    {
      "id": "total-ttc-detail-facture",
      "titre": "Détail facture : Total TTC",
      "setup": "Connecté avec le compte de démo, sur le détail d’une facture, sans filtre.",
      "etapes": [
        "Cliquer sur le lien « Retour aux factures »."
      ],
      "resultat_attendu": "Le Total TTC affiché correspond au montant TTC de la même facture dans la liste des factures.",
      "verifications": [
        "FAIL if le Total TTC affiché est différent du Montant TTC de la facture F-119 dans la liste des factures."
      ],
      "releves": [
        {
          "ecran": "detail-facture",
          "vue": "defaut"
        },
        {
          "ecran": "liste-des-factures",
          "vue": "defaut"
        }
      ],
      "regles_calculables": [
        {
          "type": "egalite",
          "a": {
            "ecran": "detail-facture",
            "champ": "Total TTC"
          },
          "b": {
            "ecran": "liste-des-factures",
            "champ": "Montant TTC de F-119"
          }
        }
      ],
      "passages_de_la_source": [
        "Le « Total TTC » du [[detail-facture]] est égal au montant de la même facture dans la [[liste-des-factures]]. Facture témoin : F-119."
      ],
      "questions": []
    }
  ]
}

